  "Nothing needs review right now.": "Gerade gibt es nichts zu prüfen.",
  "The member list could not be loaded.": "Die Mitgliederliste konnte nicht geladen werden.",
  "Rename, remove or restore members. Renames in the game follow on their own.": "Mitglieder umbenennen, entfernen oder wiederherstellen. Umbenennungen im Spiel werden von selbst übernommen.",
  "Edit Members ({count})": "Mitglieder bearbeiten ({count})",
  "Show member list": "Mitgliederliste anzeigen",
  "Rename or remove members. Removing a player who has chest history keeps their existing records but excludes them from future scans — useful when a player leaves so a new player with a similar name can't accidentally be matched into their identity.": "Mitglieder umbenennen oder entfernen. Wird ein Spieler mit Truhenverlauf entfernt, bleiben seine Einträge erhalten, er wird aber bei künftigen Scans ausgeschlossen — nützlich, wenn ein Spieler geht, damit ein neuer Spieler mit ähnlichem Namen nicht versehentlich seiner Identität zugeordnet wird.",
  "Current Name": "Aktueller Name",
  "New Name": "Neuer Name",
  "Current": "Aktuell",
  "Remove": "Entfernen",
  "Show removed members ({count})": "Entfernte Mitglieder anzeigen ({count})",
  "Players excluded from scan matching. Their chest history is intact. Restore one if it was removed by mistake or the player rejoined the clan.": "Spieler, die vom Scan-Abgleich ausgeschlossen sind. Ihr Truhenverlauf bleibt erhalten. Stelle einen wieder her, wenn er versehentlich entfernt wurde oder dem Clan wieder beigetreten ist.",
  "Last Seen": "Zuletzt",
  "Restore": "Wiederherstellen",
  "Triumphal Chest Points": "Triumph-Truhenpunkte",
  "One <strong>global scoring table</strong> for the <strong>Bank Gifts</strong> tab, tracked separately from the main leaderboard. Each value is the <strong>package price</strong> (a full 3-of-a-kind set); a single chest is worth one third of it, rounded — so three of a kind sum back to exactly the package value. Rows tagged {new} have been seen in scans but have <strong>no value yet</strong> (they score 0) — set a value to score them.": "Eine <strong>globale Wertungstabelle</strong> für den Tab <strong>Bank-Geschenke</strong>, getrennt von der Haupt-Rangliste geführt. Jeder Wert ist der <strong>Paketpreis</strong> (ein vollständiges Dreierset); eine einzelne Truhe ist ein Drittel davon wert, gerundet — drei gleiche ergeben also genau den Paketwert. Mit {new} markierte Zeilen wurden in Scans gesehen, haben aber <strong>noch keinen Wert</strong> (sie zählen 0) — setze einen Wert, damit sie zählen.",
  "New": "Neu",
  "Managed here by superadmins; values apply to every clan.": "Wird hier von Superadmins verwaltet; die Werte gelten für jeden Clan.",
  "<strong>Read-only</strong> — only a superadmin can change these values.": "<strong>Schreibgeschützt</strong> — nur ein Superadmin kann diese Werte ändern.",
  "Show triumphal chest values ({count})": "Triumph-Truhenwerte anzeigen ({count})",
  "Chests Seen": "Gesehene Truhen",
  "Per Chest": "Pro Truhe",
  "Package (3-of-a-kind)": "Paket (Dreierset)",
  "Seen in scans but has no point value yet — it currently scores 0. Set a package value to score it.": "In Scans gesehen, aber noch ohne Punktwert — zählt derzeit 0. Setze einen Paketwert, damit sie zählt.",
  "{n} seen": { one: "{n} gesehen", other: "{n} gesehen" },
  "Save All Changes": "Alle Änderungen speichern",
  "Saves every chest whose package value changed. Clear an input to remove that chest's value — it reverts to \"new\" and scores 0 until set again. Points are presentation-only, so no historical backfill is needed.": "Speichert jede Truhe, deren Paketwert sich geändert hat. Leere ein Feld, um den Wert dieser Truhe zu entfernen — sie wird wieder \"neu\" und zählt 0, bis sie erneut gesetzt wird. Punkte dienen nur der Anzeige, daher ist kein historischer Nachimport nötig.",
  "No triumphal chest data yet.": "Noch keine Triumph-Truhendaten.",
  "\"{chest}\" must be a non-negative integer": "\"{chest}\" muss eine nicht negative ganze Zahl sein",
  "No changes to save.": "Keine Änderungen zu speichern.",
  "Nothing to do": "Nichts zu tun",
  "Some changes failed:\n{errors}": "Einige Änderungen sind fehlgeschlagen:\n{errors}",
  "Partial save": "Teilweise gespeichert",
  "Saved {n} changes.": { one: "{n} Änderung gespeichert.", other: "{n} Änderungen gespeichert." },
  "Saved": "Gespeichert",
  "New Triumphal Chests": "Neue Triumph-Truhen",
  "Chest Name": "Truhenname",
  "First Seen": "Erstmals",
  "Assign each a package value under {link} on the Points tab — that scores them and clears them from this list.": "Gib jeder unter {link} im Tab „Punkte“ einen Paketwert — damit zählen sie und verschwinden aus dieser Liste.",
  "Rename failed": "Umbenennen fehlgeschlagen",
  "this member": "dieses Mitglied",
  "Remove {member}? Their chest history stays intact, but they'll be excluded from future scans so a new player with a similar name can't get matched into their identity. You can restore them later under Admin → Members → \"Show removed members\".": "{member} entfernen? Der Truhenverlauf bleibt erhalten, aber das Mitglied wird von künftigen Scans ausgeschlossen, damit ein neuer Spieler mit ähnlichem Namen nicht seiner Identität zugeordnet wird. Du kannst es später unter Admin → Mitglieder → \"Entfernte Mitglieder anzeigen\" wiederherstellen.",
  "Remove member": "Mitglied entfernen",
