  "Showing {count} of {total} — members active on at least {min} of the {n} days in this timeframe.": { one: "{count} von {total} angezeigt — Mitglieder, die an mindestens {min} von {n} Tag in diesem Zeitraum aktiv waren.", other: "{count} von {total} angezeigt — Mitglieder, die an mindestens {min} der {n} Tage in diesem Zeitraum aktiv waren." },
