  "Nobody collected a chest in this timeframe.": "Niemand hat in diesem Zeitraum eine Truhe gesammelt.",
  "Gift chests earned in this timeframe. Triumphals are scored on their {link}; end-of-event clan rewards rank nobody, so they are excluded.": "In diesem Zeitraum verdiente Geschenk-Truhen. Triumph-Truhen werden auf ihrer {link} gewertet; Clan-Belohnungen zum Eventende ranken niemanden und sind daher ausgeschlossen.",
  "own page": "eigenen Seite",
  "Game days in this timeframe on which they collected at least one chest": "Spieltage in diesem Zeitraum, an denen sie mindestens eine Truhe gesammelt haben",
  "Share of their points that came from their single biggest day. Context, not a verdict — concentrating a week's effort into an event day is a normal way to play.": "Anteil ihrer Punkte, der von ihrem stärksten Einzeltag stammt. Kontext, kein Urteil — den Einsatz einer Woche auf einen Event-Tag zu bündeln, ist eine normale Spielweise.",
  "Top Contributors": "Top-Beitragende",
