  "Change": "Änderung",
  "Nothing to compare yet — this is the first period with data on both sides.": "Noch nichts zu vergleichen — dies ist der erste Zeitraum mit Daten auf beiden Seiten.",
  "Not shown for this window: the scanner was quiet for {n} hours, longer than a gift survives, so a member looking inactive here may just be a chest nobody could capture.": { one: "Für dieses Fenster nicht angezeigt: Der Scanner war {n} Stunde still, länger als ein Geschenk überlebt, daher kann ein hier inaktiv wirkendes Mitglied einfach eine Truhe sein, die niemand erfassen konnte.", other: "Für dieses Fenster nicht angezeigt: Der Scanner war {n} Stunden still, länger als ein Geschenk überlebt, daher kann ein hier inaktiv wirkendes Mitglied einfach eine Truhe sein, die niemand erfassen konnte." },
  "Why": "Warum",
  "Previous": "Vorher",
