  "Movers": "Veränderungen",
  "Well below their own pace": "Deutlich unter dem eigenen Tempo",
  "A reason, not a verdict. Members who joined mid-period are excluded — their previous window is empty because they weren't here, which is not a drop.": "Ein Grund, kein Urteil. Mitglieder, die mitten im Zeitraum beigetreten sind, sind ausgeschlossen — ihr vorheriges Fenster ist leer, weil sie nicht da waren, und das ist kein Rückgang.",
  "Sun": "So",
