  "Thu": "Do",
  "Fri": "Fr",
  "Sat": "Sa",
  "No chests in this timeframe yet.": "Noch keine Truhen in diesem Zeitraum.",
  "None of the {n} chests in this timeframe carry a real earn time, so there is nothing to place on a clock. They were recorded before receive times were captured and only have their scan time.": { one: "Keine der {n} Truhe in diesem Zeitraum hat eine echte Verdienstzeit, daher lässt sich nichts auf einer Uhr einordnen. Sie wurde erfasst, bevor Empfangszeiten aufgezeichnet wurden, und hat nur ihre Scan-Zeit.", other: "Keine der {n} Truhen in diesem Zeitraum hat eine echte Verdienstzeit, daher lässt sich nichts auf einer Uhr einordnen. Sie wurden erfasst, bevor Empfangszeiten aufgezeichnet wurden, und haben nur ihre Scan-Zeit." },
  "Only {count} of {n} chests in this timeframe carry a real earn time — too few to read a pattern from without inventing one.": { one: "Nur {count} von {n} Truhe in diesem Zeitraum hat eine echte Verdienstzeit — zu wenige, um ein Muster abzulesen, ohne eins zu erfinden.", other: "Nur {count} von {n} Truhen in diesem Zeitraum haben eine echte Verdienstzeit — zu wenige, um ein Muster abzulesen, ohne eins zu erfinden." },
