  "Page {page} of {pages}": "Seite {page} von {pages}",
  "The Tin Man hits could not be loaded.": "Die Tin-Man-Angriffe konnten nicht geladen werden.",
  "Read from battle reports shared in the clan chat, sent in a private message to the scanner account, or shared in a chat picked under Clans → In-game. A hit nobody shared is not here.": "Gelesen aus Kampfberichten, die im Clan-Chat geteilt, per Privatnachricht an das Scanner-Konto geschickt oder in einem unter Clans → Im Spiel gewählten Chat geteilt wurden. Ein Angriff, den niemand geteilt hat, fehlt hier.",
  "The Tin Man starts with 4 stacks of monsters and drops to 3, 2 and 1 as it loses health. The stacks are the ones it had when the hit began.": "Der Tin Man beginnt mit 4 Monster-Trupps und fällt auf 3, 2 und 1, während er Gesundheit verliert. Gezählt werden die Trupps, die er zu Beginn des Angriffs hatte.",
  "{n} shared reports are still being read.": { one: "{n} geteilter Bericht wird noch gelesen.", other: "{n} geteilte Berichte werden noch gelesen." },
