  "A vault goes up within about 10 squares of the city of the member who raised it, on the first day of the run. Each scan reads the map there.": "Eine Schatzkammer erscheint am ersten Tag des Durchgangs im Umkreis von etwa 10 Feldern um die Stadt des Mitglieds, das sie errichtet hat. Jeder Scan liest dort die Karte.",
  "A vault taken down before the next scan is not seen.": "Eine Schatzkammer, die vor dem nächsten Scan erobert wird, wird nicht gesehen.",
  "Vault links are read from {chats}. A link counts for the member who posted it, and is matched to the map by tile, level and time.": "Schatzkammer-Links werden aus {chats} gelesen. Ein Link zählt für das Mitglied, das ihn gepostet hat, und wird über Feld, Stufe und Zeit der Karte zugeordnet.",
  "Pick the chat where members link their vaults under Clans → In-game → Battle reports, and this shows who posted theirs.": "Wähle unter Clans → Im Spiel → Kampfberichte den Chat, in dem Mitglieder ihre Schatzkammern verlinken, dann zeigt dies, wer seine gepostet hat.",
  "{n} vaults raised by players outside the clan were also seen nearby.": { one: "{n} Schatzkammer eines Spielers außerhalb des Clans wurde ebenfalls in der Nähe gesehen.", other: "{n} Schatzkammern von Spielern außerhalb des Clans wurden ebenfalls in der Nähe gesehen." },
