  "{name} was restored on the site": "{name} wurde auf der Seite wiederhergestellt",
  "{name} marked as left": "{name} als ausgetreten markiert",
  "The site's record, not the game's: the day it marked them gone, which can be later than the day they left.": "Eintrag der Seite, nicht des Spiels: der Tag, an dem sie den Austritt bemerkt hat – er kann später liegen als der tatsächliche Austritt.",
  "{n} joins": { one: "{n} Beitritt", other: "{n} Beitritte" },
