  "{n} returns": { one: "{n} Rückkehrer", other: "{n} Rückkehrer" },
  "{joined} · {left} in the last {days} days": "{joined} · {left} in den letzten {days} Tagen",
  "Join times are the game's own, read since {date}: anyone who left before then shows only when they left. “Marked as left” is the site's own record from before the game was read: the day it noticed, which can be later than the day they left.": "Beitrittszeiten stammen aus dem Spiel selbst, gelesen seit {date}: Wer davor gegangen ist, erscheint nur mit seinem Austritt. „Als ausgetreten markiert“ ist der eigene Eintrag der Seite aus der Zeit vor dem Lesen des Spiels: der Tag, an dem sie es bemerkt hat – er kann später liegen als der tatsächliche Austritt.",
  "The clan's roster hasn't been read from the game yet. The next scan reads it.": "Die Mitgliederliste des Clans wurde noch nicht aus dem Spiel gelesen. Der nächste Scan liest sie.",
