  "Sunday to Sunday (7 days)": "Sonntag bis Sonntag (7 Tage)",
  "Pick any day one of the weeks starts on, and how many days each lasts. Weeks start at the daily reset, {time}.": "Wähle einen beliebigen Tag, an dem eine der Wochen beginnt, und wie viele Tage jede dauert. Wochen beginnen mit dem täglichen Reset um {time}.",
  "Pick the day a week starts on, and a length of {min}–{max} days.": "Wähle den Tag, an dem eine Woche beginnt, und eine Länge von {min}–{max} Tagen.",
  "This week: <strong>{range}</strong>. The next one starts {date}.": "Diese Woche: <strong>{range}</strong>. Die nächste beginnt am {date}.",
  "In a Seasonal Kingdom, Tinman to Tinman opens when {event} ({ancients} day 2) begins at 17:00 UTC and runs until the next one begins, {n} days later.": { one: "In einem Saisonalen Königreich beginnt Tinman bis Tinman, wenn {event} ({ancients} Tag 2) um 17:00 UTC startet, und läuft bis zum Start des nächsten, {n} Tag später.", other: "In einem Saisonalen Königreich beginnt Tinman bis Tinman, wenn {event} ({ancients} Tag 2) um 17:00 UTC startet, und läuft bis zum Start des nächsten, {n} Tage später." },
  "Tinman to Tinman opens when {event} ({ancients} day 2) begins at 17:00 UTC and runs until the next one begins, six days later.": "Tinman bis Tinman beginnt, wenn {event} ({ancients} Tag 2) um 17:00 UTC startet, und läuft bis zum Start des nächsten, sechs Tage später.",
