  "Add Clan": "Clan hinzufügen",
  "Each clan has its own member roster, chest data, Total Battle login, Discord channel, and ChestTracker share code. The scanner reads every active clan in turn on each scheduled interval.": "Jeder Clan hat eine eigene Mitgliederliste, eigene Truhendaten, eine eigene Total Battle-Anmeldung, einen Discord-Kanal und einen ChestTracker-Freigabecode. Der Scanner liest bei jedem geplanten Intervall alle aktiven Clans nacheinander.",
  "Manage your clan's Discord and ChestTracker integrations and refresh the Total Battle login session.": "Verwalte die Discord- und ChestTracker-Integration deines Clans und erneuere die Total Battle-Anmeldesitzung.",
