  "Create": "Erstellen",
  "After creating, sign in to TB for the new clan via the in-app login bridge. The next scan reads its members and chests from the game.": "Melde dich nach dem Erstellen über die Fernanmeldung in der App für den neuen Clan bei TB an. Der nächste Scan liest seine Mitglieder und Truhen aus dem Spiel.",
