  "Name share link": "Freigabelink benennen",
  "Rename failed.": "Umbenennen fehlgeschlagen.",
  "Disable this share link? The URL stops working immediately and the clan’s other links are unaffected. It keeps its history and can be restored later from “Analytics & history”.": "Diesen Freigabelink deaktivieren? Die URL funktioniert sofort nicht mehr, die anderen Links des Clans sind nicht betroffen. Der Verlauf bleibt erhalten und er kann später unter „Analysen & Verlauf“ wiederhergestellt werden.",
  "Disable share link": "Freigabelink deaktivieren",
  "Disable": "Deaktivieren",
  "Failed to disable share link": "Freigabelink konnte nicht deaktiviert werden",
  "Failed to disable share link.": "Freigabelink konnte nicht deaktiviert werden.",
  "✓ Copied!": "✓ Kopiert!",
  "Click to copy": "Zum Kopieren klicken",
  "Delete clan \"{clan}\"? It disappears from the clan picker, the scanner, Discord and its public share link, and its members can no longer sign in to it.\n\nIts data — members, scans, chests, resources, settings — is KEPT, and a superadmin can put the clan back from System → Deleted Clans.": "Clan \"{clan}\" löschen? Er verschwindet aus der Clan-Auswahl, dem Scanner, Discord und seinem öffentlichen Freigabelink, und seine Mitglieder können sich nicht mehr dafür anmelden.\n\nSeine Daten — Mitglieder, Scans, Truhen, Ressourcen, Einstellungen — bleiben ERHALTEN, und ein Superadmin kann den Clan unter System → Gelöschte Clans zurückholen.",
  "Delete clan \"{clan}\"": "Clan \"{clan}\" löschen",
  "To confirm, type the clan name exactly: {clan}": "Gib zur Bestätigung den Clannamen exakt ein: {clan}",
  "Delete clan": "Clan löschen",
  "Name did not match — clan was not deleted.": "Name stimmte nicht überein — Clan wurde nicht gelöscht.",
  "A backup of the database is saved first. This takes a few seconds.": "Zuerst wird eine Sicherung der Datenbank gespeichert. Das dauert ein paar Sekunden.",
  "Deleting clan \"{clan}\"…": "Clan „{clan}“ wird gelöscht…",
