  "Goal history": "Zielverlauf",
  "Works out to <strong>{day}</strong> / day ({weekDays}-day week), <strong>{month}</strong> / month, <strong>{year}</strong> / year.": "Ergibt <strong>{day}</strong> / Tag ({weekDays}-Tage-Woche), <strong>{month}</strong> / Monat, <strong>{year}</strong> / Jahr.",
  "Last digest: never run yet — sends after the first scan following the next rollover.": "Letzte Übersicht: noch nie gelaufen — wird nach dem ersten Scan nach dem nächsten Tageswechsel gesendet.",
  "Last digest: ✓ {when}": "Letzte Übersicht: ✓ {when}",
