  // pages/member-profile.js
  "Might is the game’s measure of a player’s total strength: army, buildings, research and heroes together.": "Macht ist das Maß des Spiels für die gesamte Stärke eines Spielers: Armee, Gebäude, Forschung und Helden zusammen.",
  "The Gold Pass is the game’s paid monthly pass. The game reports who has it.": "Der Gold Pass ist der kostenpflichtige Monatspass des Spiels. Das Spiel meldet, wer ihn hat.",
  "Clan ranks in the game, highest first: {ranks}. The {leader} and {superior} ranks run the clan, and are admins on this site too.": "Clan-Ränge im Spiel, vom höchsten an: {ranks}. Die Ränge {leader} und {superior} leiten den Clan und sind auf dieser Seite auch Admins.",
  "The highest Guardsmen troop tier this player has researched: G1 is the first, each tier is stronger.": "Die höchste erforschte Gardisten-Stufe dieses Spielers: G1 ist die erste, jede Stufe ist stärker.",
  "Crypts are places on the game map that players explore. Each one explored sends a chest to the clan’s Gifts with the player’s name on it.": "Krypten sind Orte auf der Spielkarte, die Spieler erkunden. Jede erkundete Krypta schickt eine Truhe mit dem Namen des Spielers in die Geschenke des Clans.",
  "Citadels are strongholds on the map that clan members attack. A win sends chests to the clan’s Gifts.": "Zitadellen sind Festungen auf der Karte, die Clanmitglieder angreifen. Ein Sieg schickt Truhen in die Geschenke des Clans.",
  "Every chest is worth points, set by the clan for each chest and source. Points count toward the weekly goal.": "Jede Truhe ist Punkte wert, die der Clan je Truhe und Quelle festlegt. Punkte zählen für das Wochenziel.",
  "The number of points the clan asks each member to collect in a game week.": "Die Punktzahl, die der Clan von jedem Mitglied pro Spielwoche erwartet.",
  "A game day runs from 17:00 UTC to 17:00 UTC the next day, the same as in the game.": "Ein Spieltag läuft von 17:00 UTC bis 17:00 UTC am nächsten Tag, wie im Spiel.",
  "A burning city has had its walls broken by an attack. It shows on the game map until the walls are repaired.": "Bei einer brennenden Stadt wurden die Mauern bei einem Angriff zerstört. Das zeigt die Karte, bis die Mauern repariert sind.",
  "Titles are bonuses the game gives for a while, for example to the strongest players of an event.": "Titel sind Boni, die das Spiel für eine Zeit vergibt, zum Beispiel an die stärksten Spieler eines Events.",
