  "Bars are points per game day; the line is a {days}-day rolling average. An empty day means no chests were collected — it does not mean the scanner was down.": "Balken sind Punkte pro Spieltag; die Linie ist ein gleitender {days}-Tage-Durchschnitt. Ein leerer Tag heißt, dass keine Truhen gesammelt wurden — nicht, dass der Scanner ausgefallen war.",
