  "Shade the days a clan-calendar event was running, behind the curves. Hover any point to see which.": "Hinterlegt die Tage, an denen ein Event aus dem Clan-Kalender lief, hinter den Kurven. Fahre über einen Punkt, um zu sehen, welches.",
