  "Pick any members to overlay their might curves. The gold bands are days a clan-calendar event was running — hover any point to see which ones. A curve that steepens inside a band tells you that event moved the needle.": "Wähle beliebige Mitglieder, um ihre Macht-Kurven zu überlagern. Die goldenen Bänder sind Tage, an denen ein Event aus dem Clan-Kalender lief — fahre über einen Punkt, um zu sehen, welche. Eine Kurve, die innerhalb eines Bands steiler wird, zeigt, dass dieses Event etwas bewirkt hat.",
