  // pages/monster-tool.js
  "Common squads": "Gewöhnliche Trupps",
  "Rare squads": "Seltene Trupps",
  "Heroic squads": "Heldenhafte Trupps",
  "Legendary squads": "Legendäre Trupps",
  "Epic squads and bosses": "Epische Trupps und Bosse",
  "Raids": "Überfälle",
  "Citadels": "Festungen",
  "The game's monster data could not be loaded.": "Die Monsterdaten des Spiels konnten nicht geladen werden.",
  "Version": "Version",
  "Version {n}": "Version {n}",
  "Pick the target": "Ziel wählen",
  "The game keeps more than one version of this level. Pick the one whose army you see on the map.": "Das Spiel hat mehr als eine Version dieser Stufe. Wähle die, deren Armee du auf der Karte siehst.",
  "Type each troop's strength bonus from its card, read with the captains you will march with; health only where it says “needed”. Or fill them in from one of your shared battles, or let your battles suggest the army.": "Gib für jede Truppe den Stärkebonus von ihrer Karte ein, abgelesen mit den Hauptleuten, mit denen du marschierst; Gesundheit nur, wo „nötig“ steht. Oder übernimm sie aus einer deiner geteilten Schlachten, oder lass deine Schlachten die Armee vorschlagen.",
  "Bonuses from {source}, {when}.": "Boni aus {source}, {when}.",
  "Extra strength against these event monsters %": "Zusätzliche Stärke gegen diese Event-Monster %",
  "Some events give your army extra strength against their own monsters (+450% on Epic Fenrir squads in Nov 2026). A battle against this target fills it in.": "Manche Events geben deiner Armee zusätzliche Stärke gegen ihre eigenen Monster (+450 % gegen epische Fenrir-Trupps im Nov. 2026). Eine Schlacht gegen dieses Ziel trägt sie ein.",
  "Remove the {n} troops not needed": { one: "Die nicht benötigte Truppe entfernen", other: "Die {n} nicht benötigten Truppen entfernen" },
  "Suggest an army from my battles": "Armee aus meinen Schlachten vorschlagen",
  "Counts: searched by the simulator for the fewest losses with your troops and bonuses. Monsters and mercenaries are kept alive wherever any count can do it. Wins even with every bonus 3% lower. A suggested troop never goes above what you sent in one battle.": "Anzahlen: vom Simulator für die wenigsten Verluste mit deinen Truppen und Boni gesucht. Monster und Söldner bleiben am Leben, wo immer eine Anzahl das schafft. Gewinnt auch mit jedem Bonus 3 % niedriger. Eine vorgeschlagene Truppe geht nie über das hinaus, was du in einer Schlacht geschickt hast.",
  "Add the troops you will send, or let your shared battles suggest an army.": "Füge die Truppen hinzu, die du schickst, oder lass deine geteilten Schlachten eine Armee vorschlagen.",
  "you sent at most {n}": "höchstens {n} geschickt",
  "Round {n} — the monsters strike first": "Runde {n} — die Monster schlagen zuerst",
  "These troops can't beat {target} in one attack in both coin flips, even with all you sent.": "Diese Truppen können {target} nicht in einem Angriff in beiden Münzwürfen besiegen, auch nicht mit allem, was du geschickt hast.",
  "Epic squads and bosses are hit many times, by many players. Switch Counts to Manual to see what one attack of yours does, or size the stacks in Tools → Stacks.": "Epische Trupps und Bosse werden oft angegriffen, von vielen Spielern. Stelle Anzahlen auf Manuell, um zu sehen, was ein Angriff von dir bewirkt, oder bemiss die Stapel unter Werkzeuge → Trupps.",
  "Switch to Manual": "Auf Manuell stellen",
  "If the monsters strike first": "Wenn die Monster zuerst schlagen",
  "Who strikes first is a coin flip. Average: {lost}.": "Wer zuerst schlägt, ist ein Münzwurf. Durchschnitt: {lost}.",
  "<strong>The target.</strong> Every monster army and every unit's strength, health and “vs” features come from the game's own files, read again after every game patch. Monsters fight at exactly those numbers.": "<strong>Das Ziel.</strong> Jede Monsterarmee und die Stärke, Gesundheit und „gegen“-Eigenschaften jeder Einheit stammen aus den Dateien des Spiels und werden nach jedem Spiel-Patch neu gelesen. Monster kämpfen mit genau diesen Werten.",
  "<strong>The fight.</strong> The same rules as Tools → Citadel, checked against over 370,000 strikes of the clan's shared battle reports: the strongest stack acts first, each stack hits where it deals the most damage, and wounds stay all battle.": "<strong>Der Kampf.</strong> Dieselben Regeln wie unter Werkzeuge → Zitadelle, geprüft an über 370.000 Schlägen aus den geteilten Kampfberichten des Clans: Der stärkste Stapel handelt zuerst, jeder Stapel trifft dort, wo er den meisten Schaden macht, und Wunden bleiben die ganze Schlacht.",
  "<strong>Suggest an army.</strong> Your shared battles of the last week tell which troops you have, their bonuses with the captains you marched with, and the most of each you sent. The search picks counts from those for the fewest losses; monsters and mercenaries are kept alive wherever it can.": "<strong>Armee vorschlagen.</strong> Deine geteilten Schlachten der letzten Woche zeigen, welche Truppen du hast, ihre Boni mit den Hauptleuten, mit denen du marschiert bist, und das Meiste, was du von jeder geschickt hast. Die Suche wählt daraus Anzahlen für die wenigsten Verluste; Monster und Söldner bleiben am Leben, wo immer sie kann.",
  "<strong>Epic squads and bosses</strong> are not killed in one attack. Manual counts show what your attack does: what you lose, in what order, and how much of the army it kills.": "<strong>Epische Trupps und Bosse</strong> fallen nicht in einem Angriff. Manuelle Anzahlen zeigen, was dein Angriff bewirkt: was du verlierst, in welcher Reihenfolge, und wie viel der Armee er tötet.",
  "Not included: luck, the 10% less damage Corruption monsters take, and Exiles' Grove, whose defenders don't fight at their listed numbers.": "Nicht enthalten: Glück, die 10 % weniger Schaden, die Verderbnis-Monster nehmen, und der Hain der Verbannten, dessen Verteidiger nicht mit ihren gelisteten Werten kämpfen.",
  "The bonuses the game used in a battle: pick the player, then the battle. With no troops added yet, the battle's whole army and its target are taken, so you can replay it.": "Die Boni, die das Spiel in einer Schlacht verwendet hat: Wähle den Spieler, dann die Schlacht. Ist noch keine Truppe hinzugefügt, werden die ganze Armee der Schlacht und ihr Ziel übernommen, sodass du sie nachspielen kannst.",
  "Your account isn't linked to a game player yet. Ask an admin for an invite code, or use “Fill in from a battle report” to pick anyone's battle.": "Dein Konto ist noch mit keinem Spieler im Spiel verknüpft. Frag einen Admin nach einem Einladungscode, oder nutze „Aus einem Kampfbericht übernehmen“, um eine beliebige Schlacht zu wählen.",
  "Your battles show no troops this page can use.": "Deine Schlachten zeigen keine Truppen, die diese Seite verwenden kann.",
  "your {n} battles of the last week": { one: "deiner Schlacht der letzten Woche", other: "deinen {n} Schlachten der letzten Woche" },
