  "Nobody scores {pct} or more in this timeframe.": "In diesem Zeitraum erreicht niemand {pct} oder mehr.",
  "Nobody scores below {pct} in this timeframe.": "In diesem Zeitraum liegt niemand unter {pct}.",
  "+{n} more in the table below": { one: "+{n} weiteres in der Tabelle unten", other: "+{n} weitere in der Tabelle unten" },
  "Median score": "Median-Bewertung",
  "By guards level": "Nach Gardisten-Stufe",
  "{tinman} targets follow the guards level; unknown counts as G{level}": "{tinman}-Ziele richten sich nach der Gardisten-Stufe; unbekannt zählt als G{level}",
  "too little data to count yet": "noch zu wenig Daten, zählt noch nicht",
  "No weekly points goal is set": "Kein wöchentliches Punkteziel gesetzt",
  "No whole week in the clan in this timeframe": "Keine volle Woche im Clan in diesem Zeitraum",
  "Reached the weekly goal in {hits} of {n} weeks; {pct} of the goal on average": { one: "Wochenziel in {hits} von {n} Woche erreicht; im Schnitt {pct} des Ziels", other: "Wochenziel in {hits} von {n} Wochen erreicht; im Schnitt {pct} des Ziels" },
  "{n} more weeks came close to it and count as part of a hit": { one: "{n} weitere Woche war nah dran und zählt anteilig als erreicht", other: "{n} weitere Wochen waren nah dran und zählen anteilig als erreicht" },
  "No finished {tinman} run in this timeframe": "Kein abgeschlossener {tinman}-Durchgang in diesem Zeitraum",
  "{pct} of their target on average, over {n} runs": { one: "im Schnitt {pct} des eigenen Ziels, über {n} Durchgang", other: "im Schnitt {pct} des eigenen Ziels, über {n} Durchgänge" },
  "{n} runs had no targets pasted, so they are measured against the median player": { one: "Für {n} Durchgang wurden keine Ziele eingefügt, daher wird er am Median-Spieler gemessen", other: "Für {n} Durchgänge wurden keine Ziele eingefügt, daher werden sie am Median-Spieler gemessen" },
  "No finished event run in this timeframe": "Kein abgeschlossener Event-Durchgang in diesem Zeitraum",
  "Took part in {hits} of {n} event runs; {pct} of the median participant on average": { one: "An {hits} von {n} Event-Durchgang teilgenommen; im Schnitt {pct} des Median-Teilnehmers", other: "An {hits} von {n} Event-Durchgängen teilgenommen; im Schnitt {pct} des Median-Teilnehmers" },
  "Score": "Bewertung",
  "{n} days in the clan in this timeframe": { one: "{n} Tag im Clan in diesem Zeitraum", other: "{n} Tage im Clan in diesem Zeitraum" },
  "No member matches these filters.": "Kein Mitglied passt zu diesen Filtern.",
  "Page {page} of {pages} · {n} members": { one: "Seite {page} von {pages} · {n} Mitglied", other: "Seite {page} von {pages} · {n} Mitglieder" },
  "Goal": "Ziel",
  "{points} from the week of {date}": "{points} ab der Woche vom {date}",
  "The goal changed in this timeframe: {steps}.": "Das Ziel hat sich in diesem Zeitraum geändert: {steps}.",
  "weight {pct}": "Gewicht {pct}",
  "How the score works": "So wird bewertet",
  "the share of closed weeks at or above the weekly points goal that applied that week (the Leaderboard goal, now {goal} points).": "der Anteil abgeschlossener Wochen, in denen das in dieser Woche geltende wöchentliche Punkteziel erreicht oder übertroffen wurde (das Ranglisten-Ziel, derzeit {goal} Punkte).",
  "A week that misses it but reaches {near} of it counts as {credit} of a hit.": "Eine Woche, die es verfehlt, aber {near} davon erreicht, zählt als {credit} einer erreichten Woche.",
  "points each week as a share of that goal, so going over it counts: a week at 150% of the goal lifts the score as much as a {tinman} run at 150% of its target.": "die Punkte jeder Woche als Anteil dieses Ziels, also zählt auch, um wie viel es übertroffen wird: Eine Woche mit 150 % des Ziels hebt die Wertung so stark wie ein {tinman}-Durchgang mit 150 % seines Ziels.",
  "points in each finished {tinman} run against the target for their guards level, from the targets pasted on Events → Ancients.": "die Punkte in jedem abgeschlossenen {tinman}-Durchgang im Vergleich zum Ziel für die eigene Gardisten-Stufe, aus den unter Events → Ancients eingefügten Zielen.",
  "A run with no targets is measured against the median player.": "Ein Durchgang ohne Ziele wird am Median-Spieler gemessen.",
  "A run with no targets pasted doesn’t count.": "Ein Durchgang ohne eingefügte Ziele zählt nicht.",
  "It counts toward the score once there are {n} runs with targets in this timeframe.": { one: "Es zählt zur Bewertung, sobald es in diesem Zeitraum {n} Durchgang mit Zielen gibt.", other: "Es zählt zur Bewertung, sobald es in diesem Zeitraum {n} Durchgänge mit Zielen gibt." },
  "points in each finished run of {events} against the median participant. A run sat out counts as 0.": "die Punkte in jedem abgeschlossenen Durchgang von {events} im Vergleich zum Median-Teilnehmer. Ein ausgelassener Durchgang zählt als 0.",
  "A week or run only counts if the member was in the clan for all of it. Up to {from} of the goal or target, a share counts as it is; above that, every doubling adds {step}: {twice} scores {twiceScore}, and {capAt} or more scores {cap}, the most one week or run can count, so a single huge week can’t hide empty ones. The columns show the real shares.": "Eine Woche oder ein Durchgang zählt nur, wenn das Mitglied die ganze Zeit im Clan war. Bis {from} des Ziels zählt ein Anteil, wie er ist; darüber bringt jede Verdopplung {step} mehr: {twice} ergibt {twiceScore}, und ab {capAt} gibt es {cap}, das Höchste, was eine Woche oder ein Durchgang zählen kann, damit eine einzige riesige Woche leere Wochen nicht verdeckt. Die Spalten zeigen die echten Anteile.",
  "A week or run only counts if the member was in the clan for all of it, and one counts for at most {cap}, so a single huge week can’t hide empty ones.": "Eine Woche oder ein Durchgang zählt nur, wenn das Mitglied die ganze Zeit im Clan war, und jede zählt höchstens als {cap}, damit eine einzige riesige Woche leere Wochen nicht verdeckt.",
  "The score is the weighted average of the parts a member has enough data for. 100% means meeting every expectation; {over} or more is an overachiever, below {under} an underachiever.": "Die Bewertung ist der gewichtete Durchschnitt der Teile, für die ein Mitglied genug Daten hat. 100% heißt, alle Erwartungen erfüllt; ab {over} ist man über Soll, unter {under} unter Soll.",
  "To be shown, a member needs {n} days in the clan within this timeframe. Time in the clan counts from their first chest, might reading or sighting, whichever is earliest, so a renamed player keeps their old name’s history.": { one: "Um angezeigt zu werden, braucht ein Mitglied {n} Tag im Clan innerhalb dieses Zeitraums. Die Zeit im Clan zählt ab der ersten Truhe, der ersten Macht-Erfassung oder dem ersten Auftauchen, je nachdem, was am frühesten war, so behält ein umbenannter Spieler die Geschichte seines alten Namens.", other: "Um angezeigt zu werden, braucht ein Mitglied {n} Tage im Clan innerhalb dieses Zeitraums. Die Zeit im Clan zählt ab der ersten Truhe, der ersten Macht-Erfassung oder dem ersten Auftauchen, je nachdem, was am frühesten war, so behält ein umbenannter Spieler die Geschichte seines alten Namens." },
  "Days in timeframe": "Tage im Zeitraum",
  "Too new to judge ({count})": "Zu neu für eine Bewertung ({count})",
