  "this clan": "diesen Clan",
  "What each chest source is worth for <strong>{clan}</strong> — every clan has its own values; switch clan to edit another clan's.": "Was jede Truhen-Quelle für <strong>{clan}</strong> wert ist — jeder Clan hat eigene Werte; wechsle den Clan, um die eines anderen zu bearbeiten.",
  "What each chest source is worth for <strong>{clan}</strong> — every clan has its own values.": "Was jede Truhen-Quelle für <strong>{clan}</strong> wert ist — jeder Clan hat eigene Werte.",
  "Most sources pay one value for every chest they drop; the few that pay some chests differently list those under the source.": "Die meisten Quellen zahlen einen Wert für jede Truhe, die sie liefern; die wenigen, die manche Truhen anders werten, führen diese unter der Quelle auf.",
  "When you save, you choose: from today on (chests from earlier days keep their points) or for all history (every recorded chest is rescored — for fixing a wrong value).": "Beim Speichern wählst du: ab heute (Truhen früherer Tage behalten ihre Punkte) oder für den gesamten Verlauf (jede erfasste Truhe wird neu bewertet — um einen falschen Wert zu korrigieren).",
