  "Correction — all history": "Korrektur — gesamter Verlauf",
  "No value changed.": "Kein Wert hat sich geändert.",
  "A dated change applies from its game day's reset on; chests from earlier days keep the points they had. A correction to all history rescored every recorded chest, so it is kept as a record only.": "Eine datierte Änderung gilt ab dem Reset ihres Spieltags; Truhen früherer Tage behalten ihre Punkte. Eine Korrektur für den gesamten Verlauf hat jede erfasste Truhe neu bewertet und wird daher nur als Protokoll geführt.",
  "Dated changes": "Datierte Änderungen",
  "No dated changes yet. Values saved “from today on” are listed here.": "Noch keine datierten Änderungen. Werte, die „ab heute“ gespeichert werden, erscheinen hier.",
  "Corrections to all history": "Korrekturen für den gesamten Verlauf",
  "Changes made before this history was kept (November 2026) were applied to all history and are not listed.": "Änderungen von vor diesem Verlauf (November 2026) galten für den gesamten Verlauf und sind nicht aufgeführt.",
