  "Per clan": "Pro Clan",
  "Where the points move ({n} lines)": { one: "Wohin die Punkte gehen ({n} Zeile)", other: "Wohin die Punkte gehen ({n} Zeilen)" },
  "…and {n} more lines": { one: "…und {n} weitere Zeile", other: "…und {n} weitere Zeilen" },
  "chest records change": { one: "Truhen-Eintrag ändert sich", other: "Truhen-Einträge ändern sich" },
  "points in total": { one: "Punkt insgesamt", other: "Punkte insgesamt" },
  "Chests of <strong>{clan}</strong> already recorded today are rescored; everything before today keeps its points.": "Heute bereits erfasste Truhen von <strong>{clan}</strong> werden neu bewertet; alles vor heute behält seine Punkte.",
  "No chest recorded before now changes — chests of <strong>{clan}</strong> from today on score the new values.": "Keine bisher erfasste Truhe ändert sich — Truhen von <strong>{clan}</strong> ab heute erhalten die neuen Werte.",
  "This joins the change already saved for today, {day}.": "Dies wird Teil der Änderung, die für heute ({day}) schon gespeichert ist.",
  "Every stored chest record of <strong>{clan}</strong> from these sources gets the new value, whatever day it was earned.": "Jeder gespeicherte Truhen-Eintrag von <strong>{clan}</strong> aus diesen Quellen erhält den neuen Wert, egal an welchem Tag er verdient wurde.",
  "No stored chest record of <strong>{clan}</strong> changes.": "Kein gespeicherter Truhen-Eintrag von <strong>{clan}</strong> ändert sich.",
  "It replaces what the dated changes from {days} set for these chests.": { one: "Sie ersetzt, was die datierte Änderung ab {days} für diese Truhen festgelegt hat.", other: "Sie ersetzt, was die datierten Änderungen ab {days} für diese Truhen festgelegt haben." },
  "Save {n} changes for {clan}?": { one: "{n} Änderung für {clan} speichern?", other: "{n} Änderungen für {clan} speichern?" },
  "Apply to": "Anwenden auf",
  "From today on": "Ab heute",
  "Chests from game day {day} on score the new values. Chests from earlier days keep their points.": "Truhen ab Spieltag {day} erhalten die neuen Werte. Truhen früherer Tage behalten ihre Punkte.",
  "All history": "Gesamter Verlauf",
  "Every chest this clan ever recorded is rescored. Use it to fix a value that was wrong.": "Jede Truhe, die dieser Clan je erfasst hat, wird neu bewertet. Nutze das, um einen falschen Wert zu korrigieren.",
  "Note (optional, shown in the history)": "Notiz (optional, wird im Verlauf angezeigt)",
  "Nothing to save.": "Nichts zu speichern.",
  "No changes": "Keine Änderungen",
  "Those values are already in place — nothing to save.": "Diese Werte sind bereits gesetzt — nichts zu speichern.",
  "{n} changes": { one: "{n} Änderung", other: "{n} Änderungen" },
  "{changes} saved from {day} on · {records} updated · {points} pts": "{changes} ab {day} gespeichert · {records} aktualisiert · {points} Pkt.",
  "{changes} saved · {records} updated · {points} pts": "{changes} gespeichert · {records} aktualisiert · {points} Pkt.",
  "Chest points saved": "Truhen-Punkte gespeichert",
  "You have {n} unsaved changes. Recalculate only uses saved values — use Review & save first (saving updates the stored records itself).": { one: "Du hast {n} ungespeicherte Änderung. Neu berechnen nutzt nur gespeicherte Werte — nutze zuerst Prüfen & speichern (das Speichern aktualisiert die gespeicherten Einträge selbst).", other: "Du hast {n} ungespeicherte Änderungen. Neu berechnen nutzt nur gespeicherte Werte — nutze zuerst Prüfen & speichern (das Speichern aktualisiert die gespeicherten Einträge selbst)." },
  "Save your changes first": "Speichere zuerst deine Änderungen",
  "Recalculate failed": "Neuberechnung fehlgeschlagen",
  "Every stored chest record already matches the current values — saves update records as they are made.": "Alle gespeicherten Truhen-Einträge passen bereits zu den aktuellen Werten — beim Speichern werden Einträge direkt aktualisiert.",
  "Nothing to recalculate": "Nichts neu zu berechnen",
  "Recalculate chest points?": "Truhen-Punkte neu berechnen?",
  "These stored records of <strong>{clan}</strong> no longer match the values in force on the day they were earned (usually chests scanned before a value was set). Recalculating brings them in line.": "Diese gespeicherten Einträge von <strong>{clan}</strong> passen nicht mehr zu den Werten, die an ihrem Tag galten (meist Truhen, die gescannt wurden, bevor ein Wert gesetzt war). Neu berechnen gleicht sie an.",
  "Recalculated": "Neu berechnet",
  "You have {n} unsaved changes. Copying replaces every value, so save or discard them first.": { one: "Du hast {n} ungespeicherte Änderung. Kopieren ersetzt alle Werte, also speichere oder verwirf sie zuerst.", other: "Du hast {n} ungespeicherte Änderungen. Kopieren ersetzt alle Werte, also speichere oder verwirf sie zuerst." },
  "There is no other clan to copy values from.": "Es gibt keinen anderen Clan, von dem Werte kopiert werden können.",
  "Nothing to copy": "Nichts zu kopieren",
  "Every chest point value of {clan} is replaced by the other clan's. The other clan is not changed.": "Jeder Truhen-Punktwert von {clan} wird durch den des anderen Clans ersetzt. Der andere Clan bleibt unverändert.",
  "Copy values into {clan}": "Werte in {clan} kopieren",
  "Copy from": "Kopieren von",
  "Copy {from}'s values into {clan}?": "Werte von {from} in {clan} kopieren?",
  "<strong>{clan}</strong> will pay exactly what <strong>{from}</strong> pays ({n} saved values; anything {from} hasn't set uses the built-in default).": { one: "<strong>{clan}</strong> wertet dann genau wie <strong>{from}</strong> ({n} gespeicherter Wert; alles, was {from} nicht gesetzt hat, nutzt den eingebauten Standard).", other: "<strong>{clan}</strong> wertet dann genau wie <strong>{from}</strong> ({n} gespeicherte Werte; alles, was {from} nicht gesetzt hat, nutzt den eingebauten Standard)." },
  "These stored chest records of {clan} are updated right away. {from} is not changed.": "Diese gespeicherten Truhen-Einträge von {clan} werden sofort aktualisiert. {from} bleibt unverändert.",
  "No stored chest record of {clan} changes. {from} is not changed.": "Kein gespeicherter Truhen-Eintrag von {clan} ändert sich. {from} bleibt unverändert.",
  "The copied values apply to all history, so the {n} dated changes of {clan} go.": { one: "Die kopierten Werte gelten für den gesamten Verlauf, daher entfällt die datierte Änderung von {clan}.", other: "Die kopierten Werte gelten für den gesamten Verlauf, daher entfallen die {n} datierten Änderungen von {clan}." },
