  // pages/rewards-tool.js
  "{event} scores": "Punkte: {event}",
  "{event} damage": "Schaden: {event}",
  "{resource} donated": "Gespendet: {resource}",
  "The run whose ranking decides the split": "Der Durchlauf, dessen Rangliste die Aufteilung bestimmt",
  "· est.": "· gesch.",
  "Split by": "Aufteilen nach",
  "No runs to pick from": "Keine Durchläufe zur Auswahl",
  "Scores after": "Punkte nach",
  "Day {day}": "Tag {day}",
  "{n} players in the ranking read from the game, through day {day}.": { one: "{n} Spieler in der aus dem Spiel gelesenen Rangliste, bis Tag {day}.", other: "{n} Spieler in der aus dem Spiel gelesenen Rangliste, bis Tag {day}." },
  "{n} players · scores as they stood after day {day}, read from the game.": { one: "{n} Spieler · Punkte nach Tag {day}, aus dem Spiel gelesen.", other: "{n} Spieler · Punkte nach Tag {day}, aus dem Spiel gelesen." },
  "{n} players in the ranking pasted after day {day}.": { one: "{n} Spieler in der nach Tag {day} eingefügten Rangliste.", other: "{n} Spieler in der nach Tag {day} eingefügten Rangliste." },
  "{n} players · scores as they stood after day {day} (day {last} is pasted too).": { one: "{n} Spieler · Punkte wie nach Tag {day} (Tag {last} ist auch eingefügt).", other: "{n} Spieler · Punkte wie nach Tag {day} (Tag {last} ist auch eingefügt)." },
  "{n} members donated {resource} between {from} and {to}.": { one: "{n} Mitglied hat zwischen {from} und {to} {resource} gespendet.", other: "{n} Mitglieder haben zwischen {from} und {to} {resource} gespendet." },
  "No scores for this run yet — they are read from the game while the event runs.": "Noch keine Punkte für diesen Durchlauf — sie werden aus dem Spiel gelesen, solange das Event läuft.",
  "Nobody donated {resource} between {from} and {to}.": "Niemand hat zwischen {from} und {to} {resource} gespendet.",
  "The event calendar is unavailable, so this run's dates aren't known.": "Der Eventkalender ist nicht erreichbar, daher sind die Daten dieses Durchlaufs unbekannt.",
  "No runs to pick from — the event calendar is unavailable and the game has no scores for this event yet.": "Keine Durchläufe zur Auswahl — der Eventkalender ist nicht erreichbar und das Spiel hat noch keine Punkte für dieses Event.",
  "Could not load the scores.": "Die Punkte konnten nicht geladen werden.",
  "Rewards to share": "Zu verteilende Belohnungen",
  "The clan's totals": "Die Summen des Clans",
  "Clan fragments": "Clan-Fragmente",
  "Whole numbers; 7.5m and 250k work too.": "Ganze Zahlen; 7.5m und 250k gehen auch.",
  "The Clan Capital ledger could not be read.": "Die Buchungen der Clanhauptstadt konnten nicht gelesen werden.",
  "What the clan wins is credited when the run ends and fills in after the next scan.": "Was der Clan gewinnt, wird am Ende des Durchlaufs gutgeschrieben und erscheint hier nach dem nächsten Scan.",
  "This run ended before the Clan Capital ledger the scans keep begins ({date}).": "Dieser Durchlauf endete, bevor die von den Scans gespeicherten Buchungen der Clanhauptstadt beginnen ({date}).",
  "Nothing the clan won in this run is in the Clan Capital ledger.": "Was der Clan in diesem Durchlauf gewonnen hat, steht nicht in den Buchungen der Clanhauptstadt.",
  "What the clan won, credited {when}, holds no {coins} or clan fragments.": "Der Gewinn des Clans, gutgeschrieben am {when}, enthält weder {coins} noch Clan-Fragmente.",
  "Use the ledger's totals": "Summen aus den Buchungen übernehmen",
  "From the Clan Capital ledger: {items}, credited {when}.": "Aus den Buchungen der Clanhauptstadt: {items}, gutgeschrieben am {when}.",
  "Distribution": "Verteilung",
  "Include all members": "Alle Mitglieder einbeziehen",
  "<strong>{n}</strong> players share": { one: "<strong>{n}</strong> Spieler teilt", other: "<strong>{n}</strong> Spieler teilen" },
  "<strong>{n}</strong> left out": { one: "<strong>{n}</strong> ausgenommen", other: "<strong>{n}</strong> ausgenommen" },
  "{column} total <strong>{total}</strong>": "{column} gesamt <strong>{total}</strong>",
  "Enter the clan's totals above to see what each player gets.": "Trage oben die Summen des Clans ein, um zu sehen, was jeder Spieler bekommt.",
  "No player matches “{query}”.": "Kein Spieler passt zu „{query}“.",
  "No longer on the clan roster — a reward can't reach them. Tick to include anyway.": "Nicht mehr in der Clanliste — eine Belohnung kann nicht ankommen. Ankreuzen, um trotzdem einzubeziehen.",
  "left the clan": "hat den Clan verlassen",
  "Not matched to a clan member yet": "Noch keinem Clan-Mitglied zugeordnet",
  "not matched": "nicht zugeordnet",
  "{n} fragments": { one: "{n} Fragment", other: "{n} Fragmente" },
  "Leave out {name}": "{name} ausnehmen",
  "Include {name}": "{name} einbeziehen",
  "Included": "Einbezogen",
  "<strong>The pots.</strong> What the clan won in the run — the {coins} and clan fragments the game puts in the treasury when it ends — fill in from the Clan Capital ledger. Type over them to share a different amount.": "<strong>Die Töpfe.</strong> Was der Clan im Durchlauf gewonnen hat — die {coins} und Clan-Fragmente, die das Spiel an seinem Ende in die Schatzkammer legt — wird aus den Buchungen der Clanhauptstadt eingetragen. Überschreibe sie, um einen anderen Betrag zu verteilen.",
  "<strong>The split.</strong> Each player gets the pot × their score ÷ everyone's total, rounded down. The units left over go one each to the largest remainders, so the parts always add up to the pot.": "<strong>Die Aufteilung.</strong> Jeder Spieler bekommt den Topf × seine Punkte ÷ die Summe aller, abgerundet. Die übrigen Einheiten gehen einzeln an die größten Reste, sodass die Anteile immer genau den Topf ergeben.",
  "<strong>Leaving someone out.</strong> Untick them: they get nothing, and their part is spread over everyone else by score. Who you leave out is remembered in this browser.": "<strong>Jemanden ausnehmen.</strong> Haken entfernen: Der Spieler bekommt nichts, und sein Anteil wird nach Punkten auf alle anderen verteilt. Wen du ausnimmst, merkt sich dieser Browser.",
  "<strong>Left the clan.</strong> Players the roster no longer lists start unticked — a reward can only be sent to a member.": "<strong>Clan verlassen.</strong> Spieler, die nicht mehr in der Clanliste stehen, sind zunächst nicht angekreuzt — Belohnungen gehen nur an Mitglieder.",
  "<strong>{olympus}.</strong> The clan ranking on Events → {olympus}, read from the game, as it stood after the day you pick. The ranking keeps growing through the run, so the last day is the whole run.": "<strong>{olympus}.</strong> Die Clan-Rangliste unter Events → {olympus}, aus dem Spiel gelesen, wie sie nach dem gewählten Tag stand. Die Rangliste wächst über den ganzen Durchlauf, der letzte Tag ist also der ganze Durchlauf.",
  "<strong>{omens}.</strong> {essence} donated during the run, from resource tracking, or the {spoils} damage ranking on Events → {omens}, read from the game.": "<strong>{omens}.</strong> Während des Durchlaufs gespendete {essence} aus der Ressourcenerfassung, oder die Schadensrangliste von {spoils} unter Events → {omens}, aus dem Spiel gelesen.",
  "Splits like {link}. Where a leftover fragment could go either way, it may land on a different player.": "Teilt wie {link}. Wo ein übriges Fragment an den einen oder anderen gehen könnte, kann es bei einem anderen Spieler landen.",
  "totalcalculator.org's rewards page": "die Belohnungsseite von totalcalculator.org",
