  "Delete this scan and its {n} chest records? This cannot be undone.": { one: "Diesen Scan und seinen {n} Truhen-Eintrag löschen? Das kann nicht rückgängig gemacht werden.", other: "Diesen Scan und seine {n} Truhen-Einträge löschen? Das kann nicht rückgängig gemacht werden." },
  "Removed {n} chest records and the scan from history.": { one: "{n} Truhen-Eintrag und der Scan wurden aus dem Verlauf entfernt.", other: "{n} Truhen-Einträge und der Scan wurden aus dem Verlauf entfernt." },
