  "For {kills}, already lowered for a {pct}% overshoot.": "Für {kills}, bereits für {pct} % Überschuss gesenkt.",
  "Points per member": "Punkte pro Mitglied",
  "<strong>Vault pot.</strong> Each member raids one vault in {event}. Their guards level caps its size: G1 1,000 … G9 8,200 vault points.": "<strong>Schatzkammer-Topf.</strong> Jedes Mitglied plündert in {event} eine Schatzkammer. Ihr Gardisten-Level begrenzt deren Größe: G1 1.000 … G9 8.200 Schatzkammer-Punkte.",
  "<strong>What it buys.</strong> The Figurine (summons) and the Tome you pick come first. The Clock gets the rest, up to 120 minutes.": "<strong>Was er kauft.</strong> Die Figurine (Beschwörungen) und das gewählte Tome kommen zuerst. Die Clock bekommt den Rest, bis zu 120 Minuten.",
  "<strong>The target.</strong> Every summon is planned as a kill, one {tinman} level higher each time. The clan must score their combined HP plus the Tome bonus.": "<strong>Das Ziel.</strong> Jede Beschwörung wird als Kill geplant, jedes Mal ein {tinman}-Level höher. Der Clan muss deren gesamte HP plus den Tome-Bonus erzielen.",
  "<strong>The split.</strong> Each tier gets a fixed weight (G9 = 2.25× G8, and T9 = 1.75× G9). The ratios are a planning convention, not game data.": "<strong>Die Aufteilung.</strong> Jedes Tier bekommt ein festes Gewicht (G9 = 2,25× G8 und T9 = 1,75× G9). Die Verhältnisse sind eine Planungskonvention, keine Spieldaten.",
  "<strong>Summons 7 and 8</strong> are only offered while a seasonal kingdom runs.": "<strong>Beschwörungen 7 und 8</strong> gibt es nur, während ein saisonales Königreich läuft.",
  "Matches {link}, rebuilt from its outputs.": "Entspricht {link}, nachgebaut anhand seiner Ausgaben.",
