  "Total points": "Punkte gesamt",
  "No triumphal chests in this period.": "Keine Triumph-Truhen in diesem Zeitraum.",
  "Triumphal chests come from in-game package purchases. Each chest is worth one third of its package value, shown rounded to a whole number — Magic ≈83, Precious ≈33, Golden ≈17, Silver ≈7, Bronze ≈3, Wooden ≈2 — so a full set of three sums back to the package value (3 Golden = 50). These points are tracked separately from the main leaderboard.": "Triumph-Truhen stammen aus Paketkäufen im Spiel. Jede Truhe ist ein Drittel ihres Paketwerts wert, gerundet auf eine ganze Zahl — Magic ≈83, Precious ≈33, Golden ≈17, Silver ≈7, Bronze ≈3, Wooden ≈2 —, sodass ein vollständiger Satz aus drei wieder den Paketwert ergibt (3 Golden = 50). Diese Punkte werden getrennt von der Haupt-Rangliste erfasst.",
  "Recent chests": "Neueste Truhen",
